class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        V = set('aeiou')
        d = [0] * (n + 1)
        for i, ch in enumerate(s):
            d[i + 1] = d[i] + (1 if ch in V else -1)
        ans = 0
        for i in range(n):
            for j in range(i + 1, n + 1):
                if d[i] == d[j] and ((j - i) // 2) ** 2 % k == 0:
                    ans += 1
        return ans

