class Solution {
public:
    int beautifulSubstrings(string s, int k) {
        int n = s.size();
        vector<int> d(n + 1, 0);
        auto isV = [](char c) { return string("aeiou").find(c) != string::npos; };
        for (int i = 0; i < n; i++) d[i + 1] = d[i] + (isV(s[i]) ? 1 : -1);
        int ans = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j <= n; j++)
                if (d[i] == d[j]) {
                    long long h = (j - i) / 2;
                    if (h * h % k == 0) ans++;
                }
        return ans;
    }
};

