class Solution {
public:
    int beautifulSubstrings(string s, int k) {
        int n = s.size();
        long long m = 1, kk = k;
        for (long long p = 2; p * p <= kk; p++)
            if (kk % p == 0) {
                int e = 0;
                while (kk % p == 0) { kk /= p; e++; }
                for (int i = 0; i < (e + 1) / 2; i++) m *= p;
            }
        if (kk > 1) m *= kk;
        long long period = 2 * m;
        map<pair<int,long long>, int> cnt;
        auto isV = [](char c) { return string("aeiou").find(c) != string::npos; };
        int d = 0, ans = 0;
        cnt[{0, 0}] = 1;
        for (int i = 1; i <= n; i++) {
            d += isV(s[i - 1]) ? 1 : -1;
            auto key = make_pair(d, i % period);
            ans += cnt[key];
            cnt[key]++;
        }
        return ans;
    }
};

