class Solution {
    public int beautifulSubstrings(String s, int k) {
        int n = s.length();
        long m = 1, kk = k;
        for (long p = 2; p * p <= kk; p++)
            if (kk % p == 0) {
                int e = 0;
                while (kk % p == 0) { kk /= p; e++; }
                for (int i = 0; i < (e + 1) / 2; i++) m *= p;
            }
        if (kk > 1) m *= kk;
        long period = 2 * m;
        String V = "aeiou";
        Map<Long, Integer> cnt = new HashMap<>();
        int d = 0, ans = 0;
        cnt.merge(key(d, 0), 1, Integer::sum);
        for (int i = 1; i <= n; i++) {
            d += V.indexOf(s.charAt(i - 1)) >= 0 ? 1 : -1;
            long key = key(d, i % period);
            ans += cnt.getOrDefault(key, 0);
            cnt.merge(key, 1, Integer::sum);
        }
        return ans;
    }
    private long key(int d, long r) { return d * 2_000_000_007L + r; }
}

