var beautifulSubstrings = function(s, k) {
    const n = s.length, V = new Set(['a','e','i','o','u']);
    let m = 1, kk = k;
    for (let p = 2; p * p <= kk; p++)
        if (kk % p === 0) {
            let e = 0;
            while (kk % p === 0) { kk /= p; e++; }
            for (let i = 0; i < ((e + 1) >> 1); i++) m *= p;
        }
    if (kk > 1) m *= kk;
    const period = 2 * m;
    const cnt = new Map();
    let d = 0, ans = 0;
    const bump = (key, delta) => cnt.set(key, (cnt.get(key) || 0) + delta);
    bump(d + ',' + 0, 1);
    for (let i = 1; i <= n; i++) {
        d += V.has(s[i - 1]) ? 1 : -1;
        const key = d + ',' + (i % period);
        ans += cnt.get(key) || 0;
        bump(key, 1);
    }
    return ans;
};
